    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A patient has designated a "Durable Power of Attorney for Healthcare" (DPOA-HC). When does this person''s authority to make medical decisions begin?', '["As soon as the document is signed", "Only when the patient is determined by a physician to lack decision-making capacity", "Only after the patient dies", "Only in the ICU"]', 1, 'The authority of a healthcare proxy is "springing"—it only activates when the patient can no longer make their own decisions.'),
    (v_topic_id, 'Which of the following documents provides specific instructions about medical treatments the patient wants or does not want (e.g., mechanical ventilation, artificial nutrition)?', '["Healthcare Proxy", "Living Will", "Last Will and Testament", "Power of Attorney for Finances"]', 1, 'A Living Will is a "directive" that outlines specific treatment preferences.'),
    (v_topic_id, 'In the legal hierarchy of "Next-of-Kin" surrogates (in most US states), who has the highest priority after a designated proxy?', '["Adult Children", "Parents", "Spouse", "Siblings"]', 2, 'The standard hierarchy is: Legal Proxy > Spouse > Adult Children > Parents > Siblings > Close Friends.'),
    (v_topic_id, 'A surrogate is making a decision for a previously competent patient. The surrogate says: "He always valued his independence and told me he''d rather die than be on a permanent breathing machine." Which standard is the surrogate using?', '["Best Interests Standard", "Substituted Judgment Standard", "Subjective Standard", "None of the above"]', 1, 'Substituted judgment involves making the choice the patient *would have made* for themselves based on their known values and statements.'),
    (v_topic_id, 'When should a "Best Interests Standard" be used by a surrogate?', '["When the patient''s prior wishes are clearly documented", "When the patient''s prior wishes are unknown or when the patient was never competent (e.g., a child)", "When the surrogate disagrees with the patient", "None of the above"]', 1, 'The Best Interests standard is the "fallback" when no evidence of the patient''s specific values exists.'),
    (v_topic_id, 'A "POLST" (Physician Orders for Life-Sustaining Treatment) form is different from a Living Will because it is:', '["Only for healthy people", "A set of actionable medical orders signed by a physician that must be followed by EMS and other providers", "Not legally binding", "Only for use in hospitals"]', 1, 'POLST/MOLST forms turn preferences into active medical orders that travel with the patient across different care settings.'),
    (v_topic_id, 'A patient has both a "Living Will" and a "Healthcare Proxy." The proxy wants to continue a treatment that the Living Will explicitly refuses. Which typically takes precedence?', '["The Healthcare Proxy''s current decision", "The instructions in the Living Will", "The physician''s preference", "The hospital board''s policy"]', 1, 'A Living Will is a direct expression of the patient''s own autonomy and generally overrides a surrogate''s conflicting choice if the instructions are clear and applicable.'),
    (v_topic_id, 'A 65-year-old man is in a coma. He has no proxy and no spouse. He has three adult children. Two children want to stop life support, and one wants to continue. What should the physician do?', '["Follow the majority (2 vs 1)", "Work with the children to reach a consensus, potentially involving the ethics committee, as the law typically requires unanimous or at least non-conflicting agreement among equal-level surrogates", "Listen to the eldest child", "Continue life support forever"]', 1, 'Conflicts between equal-level surrogates are difficult and require mediation. Majority rule is not a legal standard in many jurisdictions for medical decisions.'),
    (v_topic_id, 'A "DNR" (Do Not Resuscitate) order means:', '["Do not treat the patient at all", "Do not perform chest compressions or defibrillation if the patient''s heart stops", "Do not provide antibiotics", "Do not intubate for respiratory failure"]', 1, 'DNR is specific to cardiac/respiratory arrest. It is NOT a "Do Not Treat" order for other conditions.'),
    (v_topic_id, 'A patient with capacity says: "I want to revoke my Living Will." How can they do this?', '["They must go back to the lawyer", "They can revoke it at any time, either in writing or orally, as long as they have the capacity to do so", "They can''t revoke it once it''s signed", "None of the above"]', 1, 'Autonomy is current; a competent patient can change their mind at any time.'),
    (v_topic_id, 'A surrogate decision-maker appears to be making a choice that is motivated by their own financial gain (e.g., inheriting the patient''s estate sooner). The physician should:', '["Ignore it, the surrogate has legal power", "Consult the ethics committee or legal counsel if there is a strong suspicion that the surrogate is not acting in the patient''s best interests or following substituted judgment", "Call the police", "None of the above"]', 1, 'A surrogate''s authority can be challenged if they are acting in bad faith or with a significant conflict of interest.'),
    (v_topic_id, 'Which of the following is true regarding "Oral" advance directives?', '["They are never valid", "Clear and repeated oral statements made to family and friends can be used as ''clear and convincing evidence'' of a patient''s wishes in some jurisdictions", "They must be notarized", "None of the above"]', 1, 'Oral statements are often the primary evidence used in "Substituted Judgment" cases.'),
    (v_topic_id, 'An "Unrepresented" or "Unbefriended" patient is one who:', '["Lacks capacity, has no advance directives, and has no identifiable surrogate", "Is homeless", "Has no insurance", "None of the above"]', 0, 'These patients are among the most vulnerable and often require a court-appointed guardian or a specific hospital committee process.'),
    (v_topic_id, 'A "DNI" (Do Not Intubate) order specifically prohibits:', '["Chest compressions", "Endotracheal intubation for respiratory failure", "Antibiotics", "Oxygen via nasal cannula"]', 1, 'DNI and DNR are separate. A patient can be a DNI but still receive CPR (without intubation) or other forms of respiratory support like BiPAP.'),
    (v_topic_id, 'A surrogate refuses a simple, low-risk, life-saving treatment for an incapacitated adult. The physician believes the patient would have wanted the treatment. The physician should:', '["Overrule the surrogate immediately", "Engage in a conflict-resolution process to understand the surrogate''s reasoning and ensure they are following the patient''s values", "Do nothing", "None of the above"]', 1, 'Respect for surrogacy is the rule, but it is not absolute if the surrogate is clearly violating the patient''s known wishes or best interests.'),
    (v_topic_id, 'The "Cruzan v. Director, Missouri Department of Health" case was significant because it:', '["Legalized euthanasia", "Established that states can require ''clear and convincing evidence'' of a patient''s wishes before life-sustaining treatment can be withdrawn", "Created Medicare", "None of the above"]', 1, 'This Supreme Court case emphasized the importance of high-quality evidence of an incapacitated patient''s prior wishes.'),
    (v_topic_id, 'A patient is in a "Persistent Vegetative State" (PVS). Their Living Will says: "No artificial nutrition." The family wants to keep the feeding tube. The physician should:', '["Keep the tube to avoid conflict", "Honor the Living Will, as it is a direct expression of the patient''s autonomy regarding their own body", "Ask the hospital lawyer", "None of the above"]', 1, 'Directives from the patient (when competent) take precedence over surrogate preferences.'),
    (v_topic_id, 'Which of the following describes "Medical Futility"?', '["The doctor is tired", "A treatment that has no reasonable chance of achieving the patient''s goals or providing a physiological benefit", "A very expensive treatment", "None of the above"]', 1, 'Futility is a common source of conflict between physicians and surrogates.'),
    (v_topic_id, 'A "Medical Power of Attorney" (MPOA) is primarily used to:', '["Make financial decisions", "Appoint a person to make medical decisions on the patient''s behalf if they lose capacity", "Decide who gets the patient''s house", "None of the above"]', 1, 'This is the most flexible type of advance directive as it appoints a "voice" rather than just a "list" of rules.'),
    (v_topic_id, 'A patient has a DNR order in the hospital. If they go into cardiac arrest in the parking lot, does the DNR still apply?', '["No, only inside the room", "Yes, if the medical team is aware of it and the hospital policy covers the entire campus", "Only if they have a tattoo", "None of the above"]', 1, 'Hospital DNR orders generally cover the entire facility, but EMS in the field may require a specific state-approved "Out-of-Hospital" DNR.'),
    (v_topic_id, 'Can a surrogate "Sign a DNR" for a patient who never discussed it?', '["No, only the patient can", "Yes, if the surrogate believes it is in the patient''s ''Best Interest'' based on the patient''s poor prognosis and the burdens of CPR", "Only if the doctor agrees", "None of the above"]', 1, 'Surrogates have the authority to make end-of-life decisions using the Best Interest standard if the patient''s wishes are unknown.'),
    (v_topic_id, 'A "Guardian ad Litem" is usually appointed to:', '["Defend the hospital", "Represent the best interests of a minor or incapacitated person in a specific legal proceeding", "Collect medical bills", "None of the above"]', 1, 'These are neutral parties appointed by a court.'),
    (v_topic_id, 'A patient with capacity signs a DNR order. Their children arrive and are upset, demanding the DNR be removed. The physician should:', '["Remove it to calm the children", "Respect the patient''s capacitated decision to remain a DNR", "Ask the children to sign a waiver", "None of the above"]', 1, 'A competent patient''s choice overrides the preferences of their family.'),
    (v_topic_id, 'Which of the following is true about "Advance Directives" across state lines?', '["They are never valid", "Most states have ''reciprocity'' laws that recognize valid advance directives from other states, though it is best to have one for the current state of residence", "You must have a national ID", "None of the above"]', 1, 'Legal recognition of out-of-state documents is common but not universal in its specifics.'),
    (v_topic_id, 'A patient is being admitted to a skilled nursing facility. Are they required to have an advance directive?', '["Yes, it''s mandatory", "No, but the ''Patient Self-Determination Act'' (PSDA) requires the facility to ask about them and provide information on how to create one", "Only if they are over 80", "None of the above"]', 1, 'The PSDA ensures that patients are informed of their right to make advance directives.'),
    (v_topic_id, 'A "Values History" is a tool that helps patients:', '["Record their medical history", "Reflect on and document their overall goals, beliefs, and what they value in life to help guide future surrogates", "Calculate their insurance premium", "None of the above"]', 1, 'This is a more qualitative approach to advance planning.'),
    (v_topic_id, 'A surrogate is being "Abusive" to the medical staff. Can their authority be revoked?', '["No, they have legal power", "Yes, a surrogate who is interfering with the safe and effective delivery of care can be challenged and potentially replaced through legal channels", "Only if they hit someone", "None of the above"]', 1, 'Surrogacy is a duty that can be forfeited if misused.'),
    (v_topic_id, 'If a patient has a "DNR" and goes into "Anaphylaxis" (allergic reaction) with respiratory distress, should they be given Epinephrine and a breathing tube?', '["No, it''s a DNR", "Yes, because the patient is not in cardiac arrest and the respiratory distress is due to a treatable, reversible cause", "Only if the family agrees", "None of the above"]', 1, 'DNR is about the *terminal* event of arrest, not about treating reversible symptoms of another condition.'),
    (v_topic_id, 'A "Living Will" says: "No tubes." The patient has a temporary blockage that can be cleared with a tube, leading to a full recovery. Should the physician place the tube?', '["No, follow the document", "Yes, most Living Wills are written for ''terminal or end-of-life'' states; if the situation is temporary and reversible, the physician should consult the surrogate to interpret the patient''s intent", "Only if the patient is a minor", "None of the above"]', 1, 'Context and intent are critical in interpreting advance directives.'),
    (v_topic_id, 'Which of the following is an example of "Non-traditional" surrogacy?', '["A spouse", "A close friend or ''Significant Other'' who is not legally married to the patient but knows their wishes best", "An adult child", "None of the above"]', 1, 'Many states now allow "close friends" to serve as surrogates if no family is available.'),
    (v_topic_id, 'A "Healthcare Proxy" is also known as:', '["A medical student", "A Durable Power of Attorney for Healthcare", "A Living Will", "None of the above"]', 1, 'These terms are often used interchangeably in clinical practice.'),
    (v_topic_id, 'A patient with capacity is about to have surgery and says: "If anything goes wrong, I want my sister, not my husband, to make the decisions." The physician should:', '["Ignore it, the husband is first", "Document this ''Oral Proxy Designation'' in the chart immediately, as it overrides the standard legal hierarchy", "Tell the husband", "None of the above"]', 1, 'A competent patient can customize their surrogate hierarchy at any time.'),
    (v_topic_id, 'A surrogate wants to "Withdraw" a treatment that was already started. Is this different from "Withholding" (not starting) the treatment?', '["Yes, withdrawing is harder legally", "Ethically and legally, there is no difference between withdrawing and withholding life-sustaining treatment", "Withdrawing is murder", "None of the above"]', 1, 'This is a common misconception. If a treatment is not meeting the patient''s goals, it can be stopped just as it could have been not started.'),
    (v_topic_id, 'Which of the following is true about "DNR" orders in the Operating Room (OR)?', '["They are always suspended", "The patient and physician should have a specific conversation about whether to suspend, modify, or maintain the DNR for the duration of the surgery", "They are never allowed in the OR", "None of the above"]', 1, 'Anesthesia inherently suppresses vital functions, making a "standing" DNR in the OR clinically complex.'),
    (v_topic_id, 'A patient is "Brain Dead." The family wants to keep the ventilator on until a relative can fly in from another country (24 hours). The physician should:', '["Refuse, it''s a waste of resources", "Generally allow this brief period of ''accommodation'' to help the family with their grief process, while clarifying that the patient is already legally dead", "Call the police", "None of the above"]', 1, 'Brief accommodations for "final goodbyes" are standard practice, even after legal death is declared.'),
    (v_topic_id, 'Can a surrogate "Demand" a treatment that is medically inappropriate (e.g., antibiotics for a viral cold)?', '["Yes, they have authority", "No, surrogates only have the authority to choose between *medically acceptable* options", "Only if they pay cash", "None of the above"]', 1, 'Surrogacy is about choosing among valid medical paths, not demanding invalid ones.'),
    (v_topic_id, 'A "Conflict of Interest" in surrogacy might occur if:', '["The surrogate likes the doctor", "The surrogate is the only person standing to inherit a large sum of money from the patient''s death", "The surrogate is a nurse", "None of the above"]', 1, 'Potential financial gain is a classic "Contextual Feature" that might bias a surrogate''s judgment.'),
    (v_topic_id, 'A patient has a "DNR-Comfort Care" (DNR-CC) order. This means:', '["They get no medicine", "They get only treatments that promote comfort (pain relief, oxygen, etc.) and no resuscitative efforts", "They must go home", "None of the above"]', 1, 'DNR-CC is a specific status in some states that focuses exclusively on symptom management.'),
    (v_topic_id, 'If a patient "Recovered Capacity" after a surrogate made a decision, who is in charge now?', '["The surrogate", "The patient", "The doctor", "None of the above"]', 1, 'Autonomy is the gold standard; surrogacy is the backup.'),
    (v_topic_id, 'A "Surrogate of Last Resort" committee in a hospital usually consists of:', '["Only surgeons", "A multidisciplinary group including physicians, nurses, social workers, and ethicists to make a ''Best Interest'' decision for an unbefriended patient", "Only the hospital CEO", "None of the above"]', 1, 'This ensures a broad and objective perspective for the most vulnerable patients.'),
    (v_topic_id, 'A patient is in a coma. The spouse says: "Don''t tell me anything, just talk to my brother, he''s the smart one." This is:', '["Legal abandonment", "A valid delegation of surrogate authority to another person", "Incompetence", "None of the above"]', 1, 'A surrogate can also "waive" their role or delegate it to someone else.'),
    (v_topic_id, 'Which of the following is true about "Advance Directives" for people with early-stage Alzheimer''s?', '["They are too late", "They are essential to complete while the patient still has the capacity to express their future wishes and values", "They only work if the patient can still drive", "None of the above"]', 1, 'Early planning is the most effective way to ensure prospective autonomy.'),
    (v_topic_id, 'A surrogate wants to "De-escalate" care (e.g., stopping blood pressure medications) for a terminal patient. The goal is:', '["To save money", "To align the intensity of care with the patient''s poor prognosis and focus on comfort", "To punish the patient", "None of the above"]', 1, 'De-escalation is a common part of end-of-life care planning.'),
    (v_topic_id, 'The "Quinlan" case established that:', '["Abortion is legal", "Families have the right to withdraw life-sustaining treatment (a ventilator) from a patient in a persistent vegetative state", "Doctors can be sued for everything", "None of the above"]', 1, 'Karen Ann Quinlan was a foundational case for the right of surrogates to make end-of-life choices.'),
    (v_topic_id, 'A "Limited Power of Attorney" might be used to:', '["Make all medical decisions", "Provide consent for a single, specific procedure while the patient is under anesthesia", "Sign a house deed", "None of the above"]', 1, 'MPOA can be broad or very narrow.'),
    (v_topic_id, 'A patient is a "DNR" and "DNI". They have a severe pneumonia. Should they be given antibiotics?', '["No, it''s end-of-life", "Yes, if the goal is to treat the pneumonia to return the patient to their baseline quality of life, and if the patient/surrogate agrees", "Only if they are in the ICU", "None of the above"]', 1, 'DNR/DNI does not mean "Do Not Treat" reversible infections.'),
    (v_topic_id, 'If a surrogate is "Indecisive" and cannot make a choice, the physician should:', '["Choose for them", "Provide more support, use ''Recommendation-based'' counseling, and involve the ethics team to help reduce the surrogate''s burden", "Fire the surrogate", "None of the above"]', 1, 'Surrogate distress is common and requires a compassionate clinical response.'),
    (v_topic_id, 'Which document is most likely to be used by "EMS" in a patient''s home?', '["A Living Will", "A state-approved ''Out-of-Hospital'' DNR or a POLST form", "A Last Will", "None of the above"]', 1, 'EMS providers need clear, actionable, and legally recognized orders to withhold resuscitation.'),
    (v_topic_id, 'A surrogate chooses a treatment that the physician thinks is "Too Risky." The physician should:', '["Refuse to do it", "Have a detailed discussion about the risk-benefit ratio and ensure the surrogate is using the ''Substituted Judgment'' standard correctly", "Do it anyway", "None of the above"]', 1, 'Surrogates are allowed to take risks that the patient would have taken.'),
    (v_topic_id, 'The ultimate goal of surrogate decision-making is to:', '["Save the hospital money", "Honor the patient''s autonomy by being their voice when they are silent", "Make the family happy", "None of the above"]', 1, 'Surrogacy is a mechanism for extending autonomy beyond the loss of capacity.');
